{
      "order": 754,
      "id": "duality-and-rigidity-in-monoidal-categories",
      "title": "Duality and Rigidity in Monoidal Categories",
      "kind": "A",
      "category": "category-theory",
      "companion": "duality-and-rigidity-in-monoidal-categories-examples",
      "requires": [
        "braided-and-symmetric-monoidal-categories-examples"
      ],
      "items": [
        {
          "id": "def-left-dual-and-right-dual-object",
          "kind": "definition",
          "title": "Left dual and right dual object",
          "deps": [
            "def-monoidal-category"
          ],
          "landmark": true
        },
        {
          "id": "def-the-zig-zag-identities",
          "kind": "definition",
          "title": "The zig-zag identities",
          "deps": [
            "def-left-dual-and-right-dual-object"
          ]
        },
        {
          "id": "rem-which-side-the-word-left-refers-to",
          "kind": "remark",
          "title": "What 'left' refers to in 'left dual'",
          "deps": [
            "def-left-dual-and-right-dual-object"
          ]
        },
        {
          "id": "thm-a-left-dual-of-an-object-has-that-object-as-a-right-dual",
          "kind": "theorem",
          "title": "A left dual of an object has that object as a right dual",
          "strategy": "Reflect the left-dual data across the two zig-zag composites to build the mirrored evaluation and coevaluation, then verify the right-dual zig-zags by straightening the same string-diagram composites.",
          "deps": [
            "def-left-dual-and-right-dual-object",
            "def-the-zig-zag-identities"
          ]
        },
        {
          "id": "thm-the-unit-is-self-dual",
          "kind": "theorem",
          "title": "The unit is self-dual",
          "strategy": "Take the evaluation and coevaluation to be the unit isomorphism and its inverse, then read the two zig-zag identities as the monoidal triangle identities specialized to the tensor unit.",
          "deps": [
            "def-left-dual-and-right-dual-object",
            "cor-the-two-unitors-agree-on-the-unit-object"
          ]
        },
        {
          "id": "thm-reversing-the-tensor-product-exchanges-left-and-right-duals",
          "kind": "theorem",
          "title": "Reversing the tensor product exchanges left and right duals",
          "strategy": "Rewrite the left-dual zig-zags in the reverse monoidal structure and observe that the tensor-order reversal turns them exactly into the right-dual zig-zags, and conversely.",
          "deps": [
            "def-left-dual-and-right-dual-object",
            "def-the-reverse-and-the-opposite-of-a-monoidal-category"
          ]
        },
        {
          "id": "thm-duals-are-unique-up-to-a-unique-compatible-isomorphism",
          "kind": "theorem",
          "title": "Duals are unique up to a unique compatible isomorphism",
          "strategy": "Compose the coevaluation of one dual with the evaluation of the other to define the comparison map, then use the zig-zag identities twice to prove both compatibility and uniqueness.",
          "deps": [
            "def-left-dual-and-right-dual-object",
            "def-the-zig-zag-identities"
          ],
          "landmark": true
        },
        {
          "id": "thm-duality-yields-adjunctions-of-tensoring-functors",
          "kind": "theorem",
          "title": "Duality yields adjunctions of tensoring functors",
          "strategy": "Transpose a map across the coevaluation and evaluation of a chosen dual object, prove the two transpose constructions are inverse, and then package them as the unit-counit data for the tensoring adjunctions.",
          "deps": [
            "def-left-dual-and-right-dual-object",
            "def-adjunction-by-unit-counit-and-triangle-identities"
          ],
          "landmark": true
        },
        {
          "id": "thm-a-dual-object-in-the-endofunctor-category-is-an-adjoint-functor",
          "kind": "theorem",
          "title": "A dual object in the endofunctor category is an adjoint functor",
          "strategy": "Read composition of endofunctors as the tensor product and compare the evaluation, coevaluation, and zig-zag identities term by term with the counit, unit, and triangle identities of an adjunction.",
          "deps": [
            "def-the-zig-zag-identities",
            "def-adjunction-by-unit-counit-and-triangle-identities"
          ],
          "landmark": true
        },
        {
          "id": "cor-a-second-proof-that-adjoints-are-unique",
          "kind": "corollary",
          "title": "A second proof that adjoints are unique",
          "strategy": "Apply dual uniqueness inside the endofunctor-composition monoidal category, where left adjoints appear exactly as left duals of the same endofunctor.",
          "deps": [
            "thm-a-dual-object-in-the-endofunctor-category-is-an-adjoint-functor",
            "thm-duals-are-unique-up-to-a-unique-compatible-isomorphism"
          ]
        },
        {
          "id": "def-rigid-object-and-rigid-monoidal-category",
          "kind": "definition",
          "title": "Rigid object and rigid monoidal category",
          "deps": [
            "def-left-dual-and-right-dual-object"
          ],
          "landmark": true
        },
        {
          "id": "cex-not-every-monoidal-category-is-rigid",
          "kind": "counterexample",
          "title": "Not every monoidal category is rigid",
          "strategy": "Use an infinite-dimensional vector space V inside the monoidal category of all vector spaces: if coev(1)=sum v_i tensor f_i were finite, then the zig-zag identity would expand every vector v as a linear combination of the finitely many v_i, contradicting infinite dimension.",
          "deps": [
            "def-rigid-object-and-rigid-monoidal-category",
            "def-dimension"
          ],
          "landmark": true
        },
        {
          "id": "thm-finite-dimensional-vector-spaces-are-rigid",
          "kind": "theorem",
          "title": "Finite-dimensional vector spaces are rigid",
          "strategy": "Work in the published monoidal category of modules over a field, choose a finite basis and dual basis, define coevaluation by the finite sum of basis vectors tensor dual basis vectors, and verify the two zig-zag identities by coordinate expansion.",
          "deps": [
            "def-rigid-object-and-rigid-monoidal-category",
            "thm-modules-over-a-commutative-ring-form-a-monoidal-category",
            "def-algebraic-dual-and-linear-functional",
            "thm-dual-family-is-a-basis-in-finite-dimension",
            "def-dimension"
          ],
          "landmark": true
        },
        {
          "id": "def-the-dual-of-a-morphism",
          "kind": "definition",
          "title": "The dual of a morphism",
          "deps": [
            "def-left-dual-and-right-dual-object"
          ]
        },
        {
          "id": "thm-left-duality-is-a-contravariant-antimonoidal-functor",
          "kind": "theorem",
          "title": "Left duality is a contravariant antimonoidal functor",
          "strategy": "Check that the transpose formula for f^vee preserves identities and reverses composition, then use uniqueness of duals together with the reversed tensor order on dual pairs to identify (X tensor Y)^vee with Y^vee tensor X^vee.",
          "deps": [
            "def-the-dual-of-a-morphism",
            "thm-duals-are-unique-up-to-a-unique-compatible-isomorphism",
            "thm-the-unit-is-self-dual"
          ]
        },
        {
          "id": "thm-the-double-dual-is-a-monoidal-functor",
          "kind": "theorem",
          "title": "The double dual is a monoidal functor",
          "strategy": "Compose the contravariant antimonoidal left-duality functor with itself, so the two order reversals cancel and the induced comparison maps assemble into a monoidal endofunctor.",
          "deps": [
            "thm-left-duality-is-a-contravariant-antimonoidal-functor"
          ]
        },
        {
          "id": "cex-left-and-right-duals-and-double-duals-need-not-collapse",
          "kind": "counterexample",
          "title": "Left and right duals, and double duals, need not collapse",
          "strategy": "Follow the source warning that a rigid category can have nontrivial double-dual functors and nonisomorphic left and right duals; the authoring step either supplies one checked witness covering both failures or downgrades this scaffold to a recorded remark rather than inventing a witness.",
          "deps": [
            "thm-the-double-dual-is-a-monoidal-functor"
          ]
        },
        {
          "id": "thm-in-a-rigid-category-every-morphism-of-monoidal-functors-is-an-isomorphism",
          "kind": "theorem",
          "title": "In a rigid category every morphism of monoidal functors is an isomorphism",
          "strategy": "Use rigidity to manufacture candidate inverses to the component on each object by inserting duals and monoidal structure maps, then verify the two composites collapse by the monoidal naturality squares and the zig-zag identities.",
          "deps": [
            "def-rigid-object-and-rigid-monoidal-category",
            "def-monoidal-natural-transformation",
            "thm-left-duality-is-a-contravariant-antimonoidal-functor",
            "thm-duals-are-unique-up-to-a-unique-compatible-isomorphism"
          ],
          "landmark": true
        },
        {
          "id": "thm-a-braided-rigid-category-has-a-drinfeld-morphism",
          "kind": "theorem",
          "title": "A braided rigid category has a Drinfeld morphism",
          "strategy": "Build u_X by threading the braiding through the coevaluation and evaluation defining the left and right duals, then prove naturality and invertibility by the hexagon identities together with rigidity.",
          "deps": [
            "def-rigid-object-and-rigid-monoidal-category",
            "def-braiding"
          ],
          "landmark": true
        },
        {
          "id": "def-the-categorical-trace-of-a-morphism-into-the-double-dual",
          "kind": "definition",
          "title": "The categorical trace of a morphism into the double dual",
          "deps": [
            "thm-the-double-dual-is-a-monoidal-functor"
          ],
          "landmark": true
        },
        {
          "id": "rem-what-is-needed-before-a-trace-can-be-written",
          "kind": "remark",
          "title": "What is needed before a trace can be written",
          "deps": [
            "def-the-categorical-trace-of-a-morphism-into-the-double-dual",
            "thm-a-braided-rigid-category-has-a-drinfeld-morphism"
          ]
        },
        {
          "id": "def-pivotal-structure",
          "kind": "definition",
          "title": "Pivotal structure",
          "deps": [
            "thm-the-double-dual-is-a-monoidal-functor"
          ],
          "landmark": true
        },
        {
          "id": "def-the-dimension-of-an-object-relative-to-a-pivotal-structure",
          "kind": "definition",
          "title": "The dimension of an object relative to a pivotal structure",
          "deps": [
            "def-the-categorical-trace-of-a-morphism-into-the-double-dual",
            "def-pivotal-structure"
          ]
        },
        {
          "id": "thm-basic-properties-of-the-categorical-trace",
          "kind": "theorem",
          "title": "Basic properties of the categorical trace",
          "strategy": "Compute the left and right traces by functoriality of duality and tensor product, deriving duality, multiplicativity, and double-dual cyclicity directly; in the additive setting, pass through the biproduct decomposition to obtain trace additivity.",
          "deps": [
            "def-the-categorical-trace-of-a-morphism-into-the-double-dual",
            "thm-left-duality-is-a-contravariant-antimonoidal-functor",
            "def-additive-category"
          ]
        },
        {
          "id": "def-twist-and-ribbon-structure",
          "kind": "definition",
          "title": "Twist and ribbon structure",
          "deps": [
            "def-braiding",
            "def-rigid-object-and-rigid-monoidal-category"
          ],
          "landmark": true
        },
        {
          "id": "thm-a-twist-on-a-braided-rigid-category-is-the-same-thing-as-a-pivotal-structure-of-drinfeld-type",
          "kind": "theorem",
          "title": "A twist on a braided rigid category is the same thing as a pivotal structure of Drinfeld type",
          "strategy": "Starting from a twist theta, compose it with the Drinfeld morphism u_X and verify the monoidal axioms; conversely, solve theta_X from a Drinfeld-type pivotal structure and check the twist equation by expanding u_{X tensor Y}.",
          "deps": [
            "thm-a-braided-rigid-category-has-a-drinfeld-morphism",
            "def-pivotal-structure",
            "def-twist-and-ribbon-structure"
          ],
          "landmark": true
        },
        {
          "id": "rem-rigidity-alone-does-not-make-a-tensor-category",
          "kind": "remark",
          "title": "Rigidity alone does not make a tensor category",
          "deps": [
            "def-rigid-object-and-rigid-monoidal-category"
          ]
        },
        {
          "id": "fs-a-trace-can-be-defined-for-an-endomorphism-in-any-monoidal-category",
          "kind": "false-statement",
          "title": "FALSE: a trace can be defined for an endomorphism in any monoidal category",
          "strategy": "Refute the claim by isolating the missing comparison V to V double-dual: without rigidity the trace is not even typed, and without a pivotal structure an endomorphism V to V does not become an input to the categorical trace.",
          "deps": [
            "rem-what-is-needed-before-a-trace-can-be-written",
            "def-pivotal-structure"
          ]
        },
        {
          "id": "fs-a-braiding-suffices-to-define-a-trace",
          "kind": "false-statement",
          "title": "FALSE: a braiding suffices to define a trace",
          "strategy": "Refute the near-miss by separating the Drinfeld morphism from a pivotal structure: a braiding gives u_X, but only a twist makes u_X theta_X into the monoidal comparison needed to trace endomorphisms.",
          "deps": [
            "rem-what-is-needed-before-a-trace-can-be-written",
            "thm-a-twist-on-a-braided-rigid-category-is-the-same-thing-as-a-pivotal-structure-of-drinfeld-type"
          ]
        },
        {
          "id": "fs-left-and-right-duals-of-an-object-are-isomorphic",
          "kind": "false-statement",
          "title": "FALSE: left and right duals of an object are isomorphic",
          "strategy": "Use the contingent witness from the noncollapse counterexample: rigid categories can separate left from right dual data even when both exist.",
          "deps": [
            "cex-left-and-right-duals-and-double-duals-need-not-collapse"
          ]
        },
        {
          "id": "fs-every-monoidal-category-is-rigid",
          "kind": "false-statement",
          "title": "FALSE: every monoidal category is rigid",
          "strategy": "Refute the claim with the monoidal category of all vector spaces, where any duality witness for an infinite-dimensional space would force a finite spanning family.",
          "deps": [
            "cex-not-every-monoidal-category-is-rigid"
          ]
        }
      ]
    }

